// ── Device Data Extraction ──────────────────────────────
document.getElementById('btn-extract-device')?.addEventListener('click', async () => {
  try {
    const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
    if (!tab) return;
    if (!tab.url.includes('elarabyportalpfs.powerappsportals.com')) {
      alert('الرجاء فتح صفحة البوابة أولاً');
      return;
    }
    chrome.tabs.sendMessage(tab.id, { action: 'EXTRACT_DEVICE_DATA' });
    window.close();
  } catch(e) { console.error('Error starting extraction', e); }
});

// ══════════════════════════════════════════════════════════
// ▼▼▼ SECOND VISIT TAB LOGIC (عقل منفصل)
// ══════════════════════════════════════════════════════════
const svInput       = document.getElementById('sv-input');
const svDelaySlider = document.getElementById('sv-delay-slider');
const svDelayLabel  = document.getElementById('sv-delay-label');
const btnSvSingle   = document.getElementById('btn-sv-single');
const btnSvBatch    = document.getElementById('btn-sv-batch');
const btnSvStop     = document.getElementById('btn-sv-stop');
const svStatusMsg   = document.getElementById('sv-status-msg');
const svProgressW   = document.getElementById('sv-progress-wrap');
const svProgressB   = document.getElementById('sv-progress-bar');
const svCounter     = document.getElementById('sv-batch-counter');
const svTaskList    = document.getElementById('sv-task-list');

let svTaskItems = {};

// Delay slider
svDelaySlider?.addEventListener('input', () => {
  svDelayLabel.textContent = (svDelaySlider.value / 1000).toFixed(1) + ' ث';
});

function setSvStatus(text, type = 'info') {
  const icons = { info: 'ℹ️', ok: '✅', error: '❌', warn: '⚠️' };
  svStatusMsg.className = `status-msg ${type}`;
  svStatusMsg.innerHTML = `<span>${icons[type] || ''} ${escapeHtml(text)}</span>`;
}

function buildSvTaskItems(tasks) {
  svTaskList.innerHTML = '';
  svTaskItems = {};
  tasks.forEach(t => {
    const div = document.createElement('div');
    div.className = 'task-item pending';
    div.innerHTML = `
      <span class="task-icon">⏳</span>
      <span class="task-id">${escapeHtml(t.orderId || t.taskId)}</span>
      <span class="task-message">في الانتظار...</span>
    `;
    svTaskList.appendChild(div);
    svTaskItems[t.taskId] = div;
  });
}

function updateSvTaskItem(taskId, status, message) {
  const div = svTaskItems[taskId];
  if (!div) return;
  div.className = `task-item ${status}`;
  div.querySelector('.task-icon').textContent = STATUS_ICON[status] || '⚙️';
  div.querySelector('.task-message').textContent = message || status;
}

function updateSvProgress(done, total) {
  const pct = total > 0 ? Math.round((done / total) * 100) : 0;
  svProgressB.style.width = pct + '%';
  svCounter.textContent = `${done} / ${total}`;
}

function setSvBatchUI(running) {
  btnSvSingle.disabled = running;
  btnSvBatch.disabled  = running;
  btnSvStop.disabled   = !running;
}

// ── Second Visit: Single ────────────────────────────────
btnSvSingle?.addEventListener('click', async () => {
  const lines = parseLines(svInput.value);
  if (!lines.length) { setSvStatus('أدخل رقم بلاغ واحد على الأقل', 'warn'); return; }
  const orderId = extractOrderId(lines[0]);
  if (!orderId) { setSvStatus('لم يتم التعرف على رقم بلاغ', 'error'); return; }

  const tab = await getActiveTab();
  if (!tab || !isPortalTab(tab)) { alert('افتح صفحة البوابة أولاً'); return; }

  const taskId = generateTaskId();
  const task = { taskId, orderId, line: lines[0], mode: 'secondVisit' };
  buildSvTaskItems([task]);
  setSvBatchUI(true);
  setSvStatus('جارٍ إغلاق: ' + orderId, 'info');

  await sendToTab(tab.id, { action: 'START_SECOND_VISIT_QUEUE', tasks: [task], tabId: tab.id });
  startSvStatusPolling(1, [task]);
});

// ── Second Visit: Batch ─────────────────────────────────
btnSvBatch?.addEventListener('click', async () => {
  const lines = parseLines(svInput.value);
  if (!lines.length) { setSvStatus('أدخل أرقام البلاغات', 'warn'); return; }

  const tab = await getActiveTab();
  if (!tab || !isPortalTab(tab)) { alert('افتح صفحة البوابة أولاً'); return; }

  const tasks = lines.map(line => {
    const orderId = extractOrderId(line);
    return { taskId: generateTaskId(), orderId: orderId || line, line, mode: 'secondVisit' };
  }).filter(t => t.orderId);

  if (!tasks.length) { setSvStatus('لم يتم التعرف على أي رقم بلاغ', 'error'); return; }

  buildSvTaskItems(tasks);
  setSvBatchUI(true);
  setSvStatus(`جارٍ إغلاق ${tasks.length} بلاغ...`, 'info');
  updateSvProgress(0, tasks.length);

  await sendToTab(tab.id, { action: 'START_SECOND_VISIT_QUEUE', tasks, tabId: tab.id });
  startSvStatusPolling(tasks.length, tasks);
});

// ── Second Visit: Stop ──────────────────────────────────
btnSvStop?.addEventListener('click', async () => {
  const tab = await getActiveTab();
  if (tab) await sendToTab(tab.id, { action: 'STOP_QUEUE' });
  setSvBatchUI(false);
  setSvStatus('تم الإيقاف', 'warn');
});

// ── Second Visit: Status Polling ────────────────────────
let _svStorageListener = null;

function startSvStatusPolling(total, tasks) {
  let doneCount = 0;
  const taskIds = tasks.map(t => t.taskId);

  if (_svStorageListener) { chrome.storage.onChanged.removeListener(_svStorageListener); _svStorageListener = null; }

  _svStorageListener = async (changes, area) => {
    if (area !== 'local') return;

    if (changes.lastStatusUpdate?.newValue) {
      const { taskId, status, message } = changes.lastStatusUpdate.newValue;
      if (taskId === 'batch' || taskId === 'batch-done') {
        if (status === 'batch-done' || status === 'stopped') {
          stopSvStatusPolling();
          const { taskResults = [] } = await chrome.storage.local.get({ taskResults: [] });
          const success = taskResults.filter(r => r.result === 'done').length;
          const failed  = taskResults.filter(r => !['done','opened'].includes(r.result)).length;
          setSvStatus(`اكتمل — نجح: ${success} | فشل: ${failed} من ${total}`, failed > 0 ? 'warn' : 'ok');
          setSvBatchUI(false);
          return;
        }
      } else {
        updateSvTaskItem(taskId, status, message);
      }
    }

    if (changes.taskResults?.newValue) {
      const taskResults = changes.taskResults.newValue;
      const newDone = taskResults.length;
      if (newDone !== doneCount) {
        doneCount = newDone;
        const success = taskResults.filter(r => r.result === 'done').length;
        const failed  = taskResults.filter(r => !['done','opened','not-found'].includes(r.result)).length;
        updateSvProgress(doneCount, total);
        setSvStatus(`جارٍ... ${doneCount}/${total} — نجح: ${success} | فشل: ${failed}`, 'info');
        taskResults.forEach(r => {
          if (taskIds.includes(r.taskId)) updateSvTaskItem(r.taskId, r.result, getResultMessage(r.result));
        });
      }
    }
  };

  chrome.storage.onChanged.addListener(_svStorageListener);
}

function stopSvStatusPolling() {
  if (_svStorageListener) { chrome.storage.onChanged.removeListener(_svStorageListener); _svStorageListener = null; }
}

