async function _runSingleLineWithRouterInner(task) {
  const cfg = await loadSelectors(); 
  let data = parseDataLine(task.line || task);
  if (task.data && task.data.forceDrainCleaning) {
    data.forceDrainCleaning = true;
  }

  if (task.mode === 'secondVisit') {
    log('⚡ Second Visit Mode Detected. Loading profiles...');
    try {
      const r = await fetch(chrome.runtime.getURL('secondVisitProfiles.json'));
      const svConfig = await r.json();
      const pageText = document.body.innerText || '';
      let matchedProfile = svConfig.profiles.find(p => new RegExp(p.pattern, 'i').test(pageText));
      if (!matchedProfile) {
        log('⚠️ No specific profile matched. Falling back to الغسالة profile.');
        matchedProfile = svConfig.profiles.find(p => p.name === 'غسالة') || svConfig.profiles[0];
      }
      log(`🎯 Matched Profile: ${matchedProfile.name}`);

      data = {
        orderId: task.orderId,
        faultCode: matchedProfile.faultSearch,
        problemCode: matchedProfile.problemCode,
        notes: svConfig.defaultComment,
        amount: svConfig.defaultAmount || '0',
        warranty: svConfig.defaultWarranty,
        spareParts: svConfig.defaultSpareParts,
        secondVisitMode: true
      };
      task.data = data;
    } catch(e) { warn('Failed to load secondVisitProfiles.json', e); }
  }

  log('📄 Router started. mode=' + (task.mode || 'normal') + ' forceDrainCleaning=' + !!data.forceDrainCleaning + ' reportType=' + (data.reportType || 'N/A'));

