const pickAndConfirm = async (items) => {
  if (searchValue === '*') {
    log('Wildcard * provided, picking first available item.');
    const match = items[0];
    if (!match) return { ok: false, reason: 'no-match' };
    const radio = match.querySelector('input[type="radio"]');
