from playwright.sync_api import sync_playwright

def run():
    with sync_playwright() as p:
        try:
            browser = p.chromium.connect_over_cdp('http://127.0.0.1:59381')
            print('Connected to browser')
            for context in browser.contexts:
                for page in context.pages:
                    if 'elaraby' in page.url.lower():
                        print('Found elaraby page:', page.url)

                        btn = page.locator('button:has-text("استخراج"), a:has-text("استخراج"), input[value="استخراج"], .btn-extract, #btn-extract').first
                        try:
                            if btn.count() > 0:
                                print('Extract button HTML:', btn.evaluate('el => el.outerHTML'))
                                print('Button ID:', btn.get_attribute('id'))
                            else:
                                print('Extract button not found by text.')
                        except Exception as e:
                            print('Error getting btn:', e)

                        print('\nChecking for widgets at bottom right...')
                        script = """() => {
                            const els = Array.from(document.querySelectorAll('div, a, button, iframe')).filter(el => {
                                const style = window.getComputedStyle(el);
                                if (style.position === 'fixed' || style.position === 'absolute') {
                                    const rect = el.getBoundingClientRect();
                                    return rect.bottom > window.innerHeight - 150 && rect.right > window.innerWidth - 150;
                                }
                                return false;
                            });
                            return els.map(el => el.outerHTML).slice(0, 5);
                        }"""
                        fixed = page.evaluate(script)
                        for html in fixed:
                            print('Fixed element:', html[:300])

                        print('\nLooking for custom scripts...')
                        script2 = """() => {
                            return Array.from(document.scripts).map(s => s.src || s.innerHTML.substring(0, 100)).filter(s => s.includes('extract') || s.includes('استخراج'));
                        }"""
                        scripts = page.evaluate(script2)
                        print('Scripts found:', scripts)
        except Exception as e:
            print('Error:', e)

if __name__ == '__main__':
    run()

